def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    cache = {}
    cache_order = []
    sentinel = object()

    def getitem(key):
        return cache[key]

    def setitem(key, value):
        cache[key] = value
        cache_order.append(key)

    def popitem():
        if not cache_order:
            return sentinel
        key = cache_order.pop()
        del cache[key]
        return key

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args + tuple(kwargs.items())
            if typed:
                key = *key, type(*args), type(**kwargs)

            result = getitem(key, sentinel)
            if result is sentinel:
                result = func(*args, **kwargs)
                setitem(key, result)
                while len(cache) > maxsize:
                    popitem()
            return result
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from functools import wraps
    from collections import OrderedDict
    from itertools import count

    class Node:
        __slots__ = ['value', 'freq']

        def __init__(self, value, freq=0):
            self.value = value
            self.freq = freq

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.data = OrderedDict()
            self.typed = typed
            self.maxsize = maxsize
            self.freq = Counter()

        def __call__(self, func):
            """Decorator to wrap function with the LFU cache."""
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (args, tuple(kwargs.items())) if self.typed else (args, frozenset(kwargs.items()))
                if key in self.data:
                    node = self.data[key]
                    self.freq[node.freq] -= 1
                    if self.freq[node.freq] == 0:
                        del self.freq[node.freq]
                    node.freq += 1
                    self.freq[node.freq] += 1
                    self.data.move_to_end(key)
                else:
                    value = func(*args, **kwargs)
                    self.data[key] = Node(value, 1)
                    self.freq[1] += 1
                    if len(self.data) > self.maxsize:
                        lfu = self.freq[min(self.freq.keys())].popitem(last=False)
                        del self.data[lfu[0]]

                return self.data[key].value

            return wrapper

    return LFUCache(maxsize, typed)()

