def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a graph where a class points to the classes it extend
    graph = {cls: [] for cls in classes}
    for cls in classes:
        for base in cls.__bases__:
            if base in classes:
                graph[base].append(cls)

    # Topological sort function
    def topologicalSort(v, visited=None, stack=None):
        visited = visited or set()
        stack = stack or []
        visited.add(v)
        for w in graph[v]:
            if w not in visited:
                topologicalSort(w, visited, stack)
        stack.insert(0, v)

    order = []
    for cls in classes:
        if cls not in order:
            topologicalSort(cls, order=order)

    # Remove classes that are not the base of any other class in the sorted order
    minimal = [order[0]]
    for cls in order[1:]:
        if any(c in minimalBases(minimal + [cls]) for c in graph[cls]):
            minimal.append(cls)

    return minimal

