def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    missing_digests = set(manifest_files) - digests_used
    if missing_digests:
        raise MissingDigestError(f"The following digests are present in the manifest but not used: {', '.join(missing_digests)}")

    unused_digests = digests_used - set(manifest_files)
    if unused_digests:
        raise UnusedDigestError(f"The following digests are used but not present in the manifest: {', '.join(unused_digests)}")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The input variable 'prior' must be an InventoryValidator object.")

    if self.root.name != prior.root.name:
        raise ValueError("The root element names of the inventories do not match.")

    if self.root.attributes != prior.root.attributes:
        raise ValueError("The root element attributes of the inventories do not match.")

    for item in self.root:
        match = False
        for p_item in prior.root:
            if item.name == p_item.name and item.attributes == p_item.attributes:
                match = True
                break
        if not match:
            raise ValueError(f"The item '{item.name}' with attributes {item.attributes} is not present in the prior inventory.")

    for item in prior.root:
        match = False
        for s_item in self.root:
            if item.name == s_item.name and item.attributes == s_item.attributes:
                match = True
                break
        if not match:
            raise ValueError(f"The item '{item.name}' with attributes {item.attributes} is present in the prior inventory but not in the current one.")

    print("Validation successful: The current inventory is a valid prior version of the given inventory.")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    if version not in inventory:
        raise ValueError("Version not found in inventory")

    for content in inventory[version].content:
        logical_path = content.logical_path
        content_files = content.content_files

        if logical_path in logical_path_map:
            logical_path_map[logical_path].update(content_files)
        else:
            logical_path_map[logical_path] = set(content_files)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    for file_elem in fixity.findall('file'):
        file_id = file_elem.get('id')
        if file_id not in manifest_files:
            raise ValueError(f"File {file_id} referenced in fixity block but not found in manifest.")

