def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def apply_absorption(expr1, expr2):
        if expr1 == expr2:
            return expr1
        return (expr1 & expr2, expr1 | expr2)

    def apply_negative_absorption(expr1, expr2):
        return (expr1 & ~expr2, expr1 | ~expr2)

    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 2:
            left, right = expr
            if isinstance(left, tuple) and isinstance(right, tuple):
                result.append(apply_absorption(left[0], right[0]))
                result.append(apply_absorption(left[0], right[1]))
                result.append(apply_absorption(left[1], right[0]))
                result.append(apply_absorption(left[1], right[1]))
            elif isinstance(left, tuple):
                result.append(apply_absorption(left[0], right))
                result.append(apply_negative_absorption(left[1], right))
            elif isinstance(right, tuple):
                result.append(apply_absorption(left, right[0]))
                result.append(apply_negative_absorption(left, right[1]))
            else:
                result.append(apply_absorption(left, right))
                result.append(apply_negative_absorption(left, right))
        else:
            result.append(expr)

    return result

