def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or not isinstance(alphabet, list):
        raise ValueError("Invalid input: number must be an integer and alphabet must be a list")

    if not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Invalid alphabet: all elements must be strings")

    if padding is not None and not isinstance(padding, int):
        raise ValueError("Invalid padding: must be an integer or None")

    if number < 0 or len(alphabet) == 0:
        raise ValueError("Invalid input: number must be non-negative and alphabet must not be empty")

    result = []
    base = len(alphabet)

    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding is not None and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

