class Time:
    """Represents a time."""

    @classmethod
    def from_ticks(cls, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        if not (0 <= ticks < 86400000000000):
            raise ValueError("Ticks must be within the range 0 <= ticks < 86400000000000")

        microseconds = ticks // 1000
        seconds = microseconds // 1000000
        microseconds %= 1000000
        minutes, seconds = divmod(seconds, 60)
        hours, minutes = divmod(minutes, 60)
        d = timedelta(hours=hours, minutes=minutes, seconds=seconds, microseconds=microseconds)

        if tz:
            dt = datetime(1970, 1, 1, tzinfo=timezone.utc) + d
            dt = dt.astimezone(tz)
        else:
            dt = datetime(1970, 1, 1) + d

        return cls(dt)

    def __init__(self, dt):
        self._dt = dt

    @property
    def dt(self):
        return self._dt

    def __repr__(self):
        return f"Time({self._dt})"

