import json
import xml.etree.ElementTree as ET
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        if isinstance(data, dict) and '@context' in data and 'subject' in data:
            webfinger_data = {
                'subject': data['subject'],
                'links': data.get('links', [])
            }
            return webfinger_data
    except json.JSONDecodeError:
        pass

    try:
        root = ET.fromstring(document)
        namespace = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        subject = root.find('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}subject', namespace).text
        links = root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link', namespace)
        parsed_links = [{'rel': link.get('rel'), 'type': link.get('type'), 'href': link.get('href')} for link in links]
        return {'subject': subject, 'links': parsed_links}
    except (ET.ParseError, KeyError):
        pass

    raise ValueError("Invalid Diaspora webfinger format")

def retrieve_and_parse_diaspora_webfinger(handle):
    """Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from bs4 import BeautifulSoup

    try:
        # Fetch the webfinger document
        response = requests.get(f"https://{handle}/.well-known/webfinger")
        response.raise_for_status()  # Raise an exception for HTTP errors

        # Parse the XML document
        soup = BeautifulSoup(response.text, 'xml')

        # Extract the primary hub URL
        hub_url = None
        links = soup.find_all('link', {'rel': 'alternate', 'type': 'application/json'})
        for link in links:
            if 'href' in link.attrs:
                hub_url = link['href']
                break

        if hub_url:
            return {'hub_url': hub_url}
        else:
            raise ValueError("Hub URL not found in webfinger document")

    except requests.RequestException as e:
        raise Exception(f"Failed to fetch webfinger document: {e}")
    except Exception as e:
        raise Exception(f"Failed to parse webfinger document: {e}")

