import yaml
from ir_validator import IRValidatorException

@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise ValueError("spec_content cannot be None")

    try:
        spec_dict = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML content: {e}") from e

    required_fields = cls.REQUIRED_FIELDS
    for field in required_fields:
        if field not in spec_dict:
            raise IRValidatorException(f"Missing required field: {field}")

    return spec_dict

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if not yaml_file:
        raise ValueError("YAML file path is required")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)
    except FileNotFoundError:
        raise FileNotFoundError(f"The file {yaml_file} does not exist")
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}")

    required_fields = cls.REQUIRED_FIELDS
    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Missing required field: {field}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    if 'include_dict' in parser_dict:
        include_path = parser_dict['include_dict']

        try:
            with open(include_path, 'r') as file:
                include_dict = eval(file.read())
        except FileNotFoundError:
            raise FileNotFoundError(f"The specified include path '{include_path}' does not exist.")
        except Exception as e:
            raise ValueError(f"Error parsing include dictionary from path '{include_path}': {e}")

        for key, value in include_dict.items():
            if key in parser_dict:
                raise DuplicateKeyError(f"The key '{key}' is already defined in the parser dictionary.")
            parser_dict[key] = value

    return parser_dict

