def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """

    if not isinstance(command_name, str):
        raise ValueError("command_name must be a string")

    if not self.command_options:
        raise LookupError("No command options defined for command: {}".format(command_name))

    options = self.command_options.get(command_name, None)

    if options is None:
        raise ValueError("No options found for command: {}".format(command_name))

    return options

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for arg in self.REQUIRED_ARGS:
        if arg not in args:
            raise ValueError(f"Required argument '{arg}' not provided.")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """

    matched_args = []
    for opt in options_spec:
        if 'required_when' in opt:
            for condition, required_arg in opt['required_when'].items():
                if args.get(condition) == required_arg and required_arg not in matched_args:
                    matched_args.append(required_arg)
    return matched_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """

    for arg, value in args.items():
        if isinstance(value, str) and len(value) > getattr(self, f"{arg}_length"):
            raise ValueError(f"The length of {arg} should not exceed {getattr(self, f'{arg}_length')} characters.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for key, value in args.items():
        choices = getattr(self, f'{key}_choices', [])
        if value not in choices:
            raise ValueError(f"Invalid value {value} for choice argument {key}. Available choices are {choices}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    if not args or not isinstance(args, dict):
        raise ValueError("Invalid input: args must be a dictionary")

    for key, value in args.items():
        if not isinstance(value, (int, float)):
            raise ValueError(f"Invalid value for {key}: value must be an integer or float")

        if 'min' not in value or 'max' not in value:
            raise ValueError(f"Invalid value for {key}: value must contain 'min' and 'max' keys")

        if value['min'] > value['max']:
            raise ValueError(f"Invalid value for {key}: 'min' cannot be greater than 'max'")

        if value['current'] < value['min'] or value['current'] > value['max']:
            raise ValueError(f"Invalid value for {key}: 'current' must be between 'min' and 'max'")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith('control_'):
            control_args[arg.replace('control_', '')] = args[arg]
        elif arg.startswith('nested_'):
            nested_args[arg.replace('nested_', '')] = args[arg]
        else:
            raise ValueError(f"Invalid argument: {arg}")

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = {}

    for key, value in extra_vars.items():
        if key in vars_dict:
            if isinstance(vars_dict[key], dict) and isinstance(value, dict):
                merge_extra_vars(vars_dict[key], value)
            else:
                vars_dict[key] = value
        else:
            vars_dict[key] = value

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """

    # Validate input parameters
    if not isinstance(ir_workspace, InfraredWorkspace):
        raise ValueError("ir_workspace must be an instance of InfraredWorkspace")
    if not isinstance(ir_plugin, InfraredPlugin):
        raise ValueError("ir_plugin must be an instance of InfraredPlugin")
    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a string")
    if verbose is not None and not (isinstance(verbose, int) and 0 <= verbose <= 4):
        raise ValueError("verbose must be an integer between 0 and 4 if specified")
    if extra_vars is not None and not (isinstance(extra_vars, dict)):
        raise ValueError("extra_vars must be a dictionary if specified")
    if ansible_args is not None and not (isinstance(ansible_args, dict)):
        raise ValueError("ansible_args must be a dictionary if specified")

    # Construct the command
    command = ["ansible-playbook", playbook_path]
    if verbose is not None:
        command.extend(["-v"] * verbose)
    if extra_vars is not None:
        for key, value in extra_vars.items():
            command.extend(["--extra-vars", f"{key}={value}"])
    if ansible_args is not None:
        command.extend([f"--{key.replace('_', '-')}", str(value)] for key, value in ansible_args.items())

    # Execute the command
    try:
        result = subprocess.run(command, check=True, capture_output=True, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(e.returncode, e.cmd, e.output, e.stderr)

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    for key, value in values_dict.items():
        if parser_name == 'main':
            if key in ['--int_arg', '--bool_arg']:
                if value.lower() == 'true':
                    values_dict[key] = True
                elif value.lower() == 'false':
                    values_dict[key] = False
                else:
                    values_dict[key] = int(value)
        elif parser_name == 'virsh':
            if key == '--max_value':
                if value.isdigit():
                    values_dict[key] = int(value)
                else:
                    raise ValueError(f"Invalid max_value: {value}")
        elif parser_name == 'ospd':
            if key == '--list_items':
                values_dict[key] = value.split(',')

    return values_dict

import os
import json

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """

    if not os.path.exists(plugin_dir):
        raise FileNotFoundError(f"Plugin directory {plugin_dir} does not exist")

    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_path):
        raise FileNotFoundError(f"Plugin spec file does not exist at {spec_path}")

    with open(spec_path, 'r') as f:
        spec_data = json.load(f)

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec_data)

